  width: var(--cube-size);
  height: var(--cube-size);
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.52s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: transform;
}
.die-3d-cube.is-tumbling-3d {
  transition: transform 0.42s cubic-bezier(0.36, 0.07, 0.19, 0.97);
}
.die-3d-core-plane {
  position: absolute;
  inset: 1px;
  background: #d97706;
  border-radius: 4px;
  pointer-events: none;
}
.die-3d-core-x { transform: rotateY(90deg); }
.die-3d-core-y { transform: rotateX(90deg); }
.die-3d-core-z { transform: translateZ(0px); }
