};

const die3dSpinState = {
  dieFace0: { spinsX: 0, spinsY: 0, spinsZ: 0, lastVal: 6 },
  dieFace1: { spinsX: 0, spinsY: 0, spinsZ: 0, lastVal: 6 },
  replayDieFace0: { spinsX: 0, spinsY: 0, spinsZ: 0, lastVal: 6 },
  replayDieFace1: { spinsX: 0, spinsY: 0, spinsZ: 0, lastVal: 6 }
};

