function ensure3dCubeDom(container) {
  if (!container) return null;
  let cube = container.querySelector('.die-3d-cube');
  if (cube) return cube;
  container.innerHTML = '';
  container.classList.add('die-3d-scene');
  cube = document.createElement('div');
  cube.className = 'die-3d-cube';

  ['x', 'y', 'z'].forEach(function (axis) {
    const core = document.createElement('div');
    core.className = 'die-3d-core-plane die-3d-core-' + axis;
    cube.appendChild(core);
  });

  [1, 2, 3, 4, 5, 6].forEach(function (faceVal) {
    const faceEl = document.createElement('div');
    faceEl.className = 'die-3d-face die-3d-face-' + faceVal;
    const pips = PIP_LAYOUTS[faceVal] || [4];
    const isRedPip = (faceVal === 1 || faceVal === 6);
    for (let i = 0; i < 9; i++) {
      const cell = document.createElement('div');
      if (pips.includes(i)) {
        cell.className = 'die-3d-pip ' + (isRedPip ? 'pip-red' : 'pip-dark');
      }
      faceEl.appendChild(cell);
    }
    cube.appendChild(faceEl);
  });

  container.appendChild(cube);
  return cube;
}

