  const rx = base.rx + st.spinsX * 360;
  const ry = base.ry + st.spinsY * 360;
  const rz = base.rz + st.spinsZ * 360;

  cube.classList.remove('is-tumbling-3d');
  cube.classList.toggle('die-used-dim', Boolean(isUsed));
  cube.style.transform = 'rotateX(' + rx + 'deg) rotateY(' + ry + 'deg) rotateZ(' + rz + 'deg)';
}

